mapper.select:
WITH bounds AS ( SELECT ST_TileEnvelope(#{z}, #{x}, #{y}) AS g3857, ST_Transform(ST_TileEnvelope(#{z}, #{x}, #{y}), 4326) AS g4326 ), rows AS ( SELECT ST_AsMVTGeom( ST_Transform(, 3857), b.g3857, 4096, 64, true ) AS geom, COALESCE(f.name, '') AS name, f.sub_type AS subtype, f.layer AS layer, f.region_code AS region, CAST(f.osm_id AS text) AS osm_id FROM osm_feature f CROSS JOIN bounds b WHERE f.layer = #{layer}
)
SELECT encode(ST_AsMVT(rows, #{layer}, 4096, 'geom'), 'base64') FROM rows WHERE geom IS NOT NULL
